#!/bin/bash
# Generated by macos/make-app.sh from macos/launcher.sh - re-run that script
# if the repo moves.
REPO="@REPO@"
UV="@UV@"
LOG="$HOME/.voxscribe/voxscribe.log"
PENDING="$HOME/.voxscribe/update-pending.txt"
# This script is <bundle>/Contents/MacOS/VoxScribe. The app hands an Update
# back to the bundle through it (voxscribe/updates.py, start_launcher()).
BUNDLE="$(cd "$(dirname "$0")/../.." && pwd)"

fail() {
    /usr/bin/osascript -e "display alert \"VoxScribe could not start\" message \"$1\" as critical" >/dev/null 2>&1
    exit 1
}

mkdir -p "$HOME/.voxscribe"
[ -d "$REPO" ] || fail "The repo folder $REPO no longer exists. Re-run macos/make-app.sh from its new location."
cd "$REPO" || exit 1
[ -x "$UV" ] || UV="$(command -v uv)"

# Install a pending Update first (the app left the marker and quit, see
# voxscribe/updates.py): check out the new Release, sync, roll back on any
# failure - the same module and steps as VoxScribe.bat. This script lives in
# the bundle, not the repo, so the checkout can't change it while it runs.
# The marker is deleted here too, in case Python failed before getting to it.
if [ -f "$PENDING" ] && [ -x .venv/bin/python ]; then
    .venv/bin/python -m voxscribe.updates apply-pending --uv "$UV" >>"$LOG" 2>&1
    rm -f "$PENDING"
fi

# Sync only when the lock file changed since the last successful sync.
STAMP=".venv/.voxscribe-synced-uv.lock"
if [ ! -x .venv/bin/python ] || ! cmp -s uv.lock "$STAMP" 2>/dev/null; then
    [ -x "$UV" ] || fail "uv was not found."
    "$UV" sync >>"$LOG" 2>&1 || fail "Updating the environment failed - see $LOG."
    cp uv.lock "$STAMP"
fi

# Build the helpers if missing, or rebuild them when their source is newer -
# an Update's checkout changes the source, and the binaries are gitignored.
NEED_BUILD=0
for helper in SpeechAnalyzerTranscribe SystemAudioCapture; do
    if [ ! -x "macos/$helper" ] || [ "macos/$helper.swift" -nt "macos/$helper" ]; then
        NEED_BUILD=1
    fi
done
if [ "$NEED_BUILD" = 1 ]; then
    (cd macos && ./build.sh) >>"$LOG" 2>&1 || fail "Building the Swift helpers failed - see $LOG."
fi

# "Install and quit" in the app's Update notice (#55): the app started this
# launcher only to install the Update, so don't start the app again.
[ -n "$VOXSCRIBE_NO_START" ] && exit 0

export VIRTUAL_ENV="$REPO/.venv"
export VOXSCRIBE_APP_BUNDLE="$BUNDLE"
exec .venv/bin/python gui_qt.py >>"$LOG" 2>&1
